  f:=strings.Fields(content);v:=soa;if len(f)>=7{v.NS=mustName(canonical(f[0]));v.MBox=mustName(canonical(f[1]));nums:=[]*uint32{&v.Serial,&v.Refresh,&v.Retry,&v.Expire,&v.MinTTL};for i,p:=range nums{n,_:=strconv.ParseUint(f[i+2],10,32);*p=uint32(n)}}
