text(await tools.exec_command({cmd:"cat > ops/nginx-throughput.conf <<'EOF'
keepalive_timeout 15s;
keepalive_requests 10000;
ssl_session_cache shared:SSL:20m;
ssl_session_timeout 10m;
client_body_buffer_size 512k;
proxy_request_buffering off;
proxy_buffer_size 16k;
proxy_buffers 16 16k;
proxy_max_temp_file_size 0;
EOF
scp ops/nginx-throughput.conf s1:/home/isucon/ && ssh s1 'sudo cp /home/isucon/nginx-throughput.conf /etc/nginx/conf.d/throughput.conf; sudo sed -i "/worker_processes/a worker_rlimit_nofile 65536;" /etc/nginx/nginx.conf; sudo sed -i "s/worker_connections 4096/worker_connections 16384/" /etc/nginx/nginx.conf; sudo mkdir -p /etc/systemd/system/nginx.service.d; printf "[Service]\nLimitNOFILE=65536\n" | sudo tee /etc/systemd/system/nginx.service.d/limits.conf >/dev/null; sudo systemctl daemon-reload; sudo nginx -t && sudo systemctl restart nginx; sudo cat /proc/$(pgrep -n nginx)/limits | grep files; sudo truncate -s0 /var/log/nginx/perf.log; sudo truncate -s0 /var/log/nginx/error.log' && /work/ops/run.sh 7",yield_time_ms:1000,max_output_tokens:1500}));

