package main

import (
 "net/http"
 "strconv"
 "github.com/labstack/echo/v4"
)

type LivestreamStatistics struct {
 Rank int64 `json:"rank"`
 ViewersCount int64 `json:"viewers_count"`
 TotalReactions int64 `json:"total_reactions"`
 TotalReports int64 `json:"total_reports"`
 MaxTip int64 `json:"max_tip"`
}
type UserStatistics struct {
 Rank int64 `json:"rank"`
 ViewersCount int64 `json:"viewers_count"`
 TotalReactions int64 `json:"total_reactions"`
 TotalLivecomments int64 `json:"total_livecomments"`
 TotalTip int64 `json:"total_tip"`
 FavoriteEmoji string `json:"favorite_emoji"`
}
func getUserStatisticsHandler(c echo.Context)error{
 if err:=verifyUserSession(c);err!=nil{return err}
 u,err:=userByName(c.Request().Context(),nil,c.Param("username"));if err!=nil{return echo.NewHTTPError(http.StatusBadRequest,"not found user that has the given username")}
 totals:=make(map[int64]UserStatistics)
 statistics.RLock()
 for _,s:=range statistics.streams{v:=totals[s.OwnerID];v.ViewersCount+=s.Viewers;v.TotalReactions+=s.Reactions;v.TotalLivecomments+=s.Comments;v.TotalTip+=s.Tips;totals[s.OwnerID]=v}
 result:=totals[u.ID];result.Rank=1
 var favoriteCount int64
 for emoji,count:=range statistics.emojis[u.ID]{if count>favoriteCount || count==favoriteCount&&emoji>result.FavoriteEmoji{favoriteCount=count;result.FavoriteEmoji=emoji}}
 statistics.RUnlock()
 score:=result.TotalReactions+result.TotalTip
 cached.RLock();for id,user:=range cached.users{v:=totals[id];other:=v.TotalReactions+v.TotalTip;if other>score || other==score&&user.Name>u.Name{result.Rank++}};cached.RUnlock()
 return c.JSON(200,result)
}
func getLivestreamStatisticsHandler(c echo.Context)error{
 if err:=verifyUserSession(c);err!=nil{return err}
 id,err:=strconv.ParseInt(c.Param("livestream_id"),10,64);if err!=nil{return echo.NewHTTPError(400,"livestream_id in path must be integer")}
 statistics.RLock();s,ok:=statistics.streams[id];if !ok{statistics.RUnlock();return echo.NewHTTPError(400,"cannot get stats of not found livestream")}
 rank:=int64(1);score:=s.Tips+s.Reactions
 for otherID,other:=range statistics.streams{otherScore:=other.Tips+other.Reactions;if otherScore>score || otherScore==score&&otherID>id{rank++}}
 statistics.RUnlock()
 return c.JSON(200,LivestreamStatistics{Rank:rank,ViewersCount:s.Viewers,TotalReactions:s.Reactions,TotalReports:s.Reports,MaxTip:s.MaxTip})
}
EOF
